const results = await Promise.allSettled([
  tools.exec_command({cmd:"find build/lib/trl -maxdepth 3 -type f | sort | sed -n '1,240p'",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:20000}),
  tools.exec_command({cmd:"sed -n '360,760p' src/trl/losses/grpo_loss.py",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"sed -n '1020,1085p' src/trl/trainer/grpo_trainer.py; sed -n '1540,1650p' src/trl/trainer/grpo_trainer.py; sed -n '1820,2040p' src/trl/trainer/grpo_trainer.py; sed -n '2040,2220p' src/trl/trainer/grpo_trainer.py",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:50000}),
  tools.exec_command({cmd:"python - <<'PY'
import glob,numpy as np,os,collections
fs=sorted(glob.glob('results/token_records/*.npz'))
print('n',len(fs))
for f in fs[:3]+fs[-3:]:
 x=np.load(f)
 print('\n',os.path.basename(f))
 for k,v in x.items():
  if getattr(v,'shape',())==(): print(k, repr(v.item()),type(v.item()))
  else:
   print(k, v.shape, v.dtype, 'min',float(v.min()),'max',float(v.max()),'mean',float(v.mean()),'sum',float(v.sum()))
# overall
for k in ['loss','generation_token_count','accumulation_steps','generation_steps','world_size','clip_low','clip_high']:
 vals=[float(np.load(f)[k]) for f in fs]
 print(k,'uniq',sorted(set(vals))[:10], 'range',min(vals),max(vals))
# advantages stats & masks
for f in fs:
 x=np.load(f); a=x['advantages']; m=x['mask']; lp=x['logps']; op=x['old_logps'];
 print(os.path.basename(f), 'adv',np.unique(a,return_counts=True),'mask_sum',m.sum(axis=1).tolist(),'logdelta',float(np.abs(lp-op).max()), 'loss',float(x['loss']))
PY",workdir:"/workspace",yield_time_ms":10000,max_output_tokens:40000}),
  tools.exec_command({cmd:"python - <<'PY'
import json,collections
rows=[json.loads(x) for x in open('results/metrics_rank0.jsonl')]
for r in rows:
 print(json.dumps({k:r.get(k) for k in ['step','loss','grad_norm','reward','reward_std','frac_reward_zero_std','entropy','num_tokens','completions/mean_length','completions/clipped_ratio']},sort_keys=False))
roll=[json.loads(x) for x in open('results/rollouts_rank0.jsonl')]
print('n roll',len(roll))
for s in sorted(set(r['step'] for r in roll)):
 rs=[r for r in roll if r['step']==s]
 print('step',s,'n',len(rs),'rewards',collections.Counter(r['reward'] for r in rs),'parsed',sum(r['parsed'] is not None for r in rs),'lengths',collections.Counter(len(r['completion']) for r in rs).most_common(3))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:40000})
]);
for (const r of results) { text(r.status === "fulfilled" ? r.value.output : String(r.reason)); }

